/**
 * Select custom del panel admin.
 * Mejora progresivamente los <select> nativos con un desplegable totalmente
 * estilizable (tema oscuro de marca), manteniendo el <select> oculto como
 * fuente de verdad para el envío de formularios. La lista se monta en <body>
 * (portal) y se posiciona fija para no ser recortada por tarjetas con overflow.
 *
 * Se excluyen las vistas operativas (mapa y áreas) y cualquier select
 * marcado con [data-native]. Dentro de esas vistas, un select puede pedir el
 * componente explícitamente con [data-enhance]: así el POS estiliza el de
 * mesero sin arrastrar consigo al resto de la pantalla.
 */
(function () {
    var uid = 0;
    var EXCLUDE = '.mapa-page, .area-page';
    var registry = [];
    var instancias = [];

    /**
     * Da nombre accesible al disparador. El <label for> del formulario apunta
     * al <select> nativo, que queda oculto, así que el control que se ve no
     * tenía nombre: el lector anunciaba sólo el valor elegido —«Abarrotes El
     * Puente»— sin decir de qué campo era.
     *
     * Orden: la <label> del select (y su clic pasa a enfocar el disparador, que
     * es lo que hace una etiqueta con un campo nativo); si no hay, su
     * aria-label; y si tampoco, el propio valor, que era el comportamiento de
     * antes. Con rol combobox el nombre no sale del contenido, por eso hay que
     * darlo siempre.
     */
    function nombrar(select, trigger, id) {
        var etiqueta = select.labels && select.labels.length ? select.labels[0] : null;

        if (etiqueta) {
            if (!etiqueta.id) {
                etiqueta.id = id + '-rotulo';
            }
            trigger.setAttribute('aria-labelledby', etiqueta.id);
            etiqueta.addEventListener('click', function (event) {
                event.preventDefault();
                if (!trigger.disabled) {
                    trigger.focus();
                }
            });
            return;
        }

        if (select.getAttribute('aria-label')) {
            trigger.setAttribute('aria-label', select.getAttribute('aria-label'));
            return;
        }

        trigger.setAttribute('aria-labelledby', id + '-valor');
    }

    function enhance(select) {
        if (
            select.dataset.enhanced
            || select.multiple
            || (select.closest(EXCLUDE) && !select.hasAttribute('data-enhance'))
        ) {
            return;
        }
        select.dataset.enhanced = '1';

        var id = 'admin-select-' + (++uid);

        var wrapper = document.createElement('div');
        wrapper.className = 'admin-select';
        if (select.disabled) {
            wrapper.classList.add('is-disabled');
        }
        select.parentNode.insertBefore(wrapper, select);
        wrapper.appendChild(select);
        select.classList.add('admin-select__native');
        select.setAttribute('tabindex', '-1');
        select.setAttribute('aria-hidden', 'true');

        var trigger = document.createElement('button');
        trigger.type = 'button';
        trigger.className = 'admin-select__trigger';
        /*
         * combobox y no un botón a secas: es el patrón «select-only combobox».
         * Con el rol de botón, el aria-activedescendant de abajo no lo
         * reconoce ningún lector (no es un atributo válido en un botón) y las
         * flechas movían una opción que nadie oía. Un <button> admite el rol
         * combobox, así que conserva el foco, el Enter y el clic nativos.
         */
        trigger.setAttribute('role', 'combobox');
        trigger.setAttribute('aria-haspopup', 'listbox');
        trigger.setAttribute('aria-expanded', 'false');
        trigger.setAttribute('aria-controls', id);
        if (select.disabled) {
            trigger.disabled = true;
        }
        trigger.innerHTML =
            '<span class="admin-select__value" id="' + id + '-valor"></span>' +
            '<svg class="admin-select__chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
            'stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
            '<path d="m6 9 6 6 6-6"/></svg>';
        wrapper.appendChild(trigger);
        nombrar(select, trigger, id);

        var list = document.createElement('ul');
        list.className = 'admin-select__list';
        list.id = id;
        list.setAttribute('role', 'listbox');
        // La lista se llama como su campo: se porta a <body>, lejos de la
        // etiqueta, y sin nombre el lector la anunciaba como «lista» a secas.
        if (trigger.getAttribute('aria-labelledby')) {
            list.setAttribute('aria-labelledby', trigger.getAttribute('aria-labelledby'));
        } else if (trigger.getAttribute('aria-label')) {
            list.setAttribute('aria-label', trigger.getAttribute('aria-label'));
        }
        list.hidden = true;

        var valueEl = trigger.querySelector('.admin-select__value');
        var options = [];
        var activeLi = null;
        var open = false;

        function build() {
            list.innerHTML = '';
            options = Array.prototype.map.call(select.options, function (opt, i) {
                var li = document.createElement('li');
                li.className = 'admin-select__option';
                li.id = id + '-opt-' + i;
                li.setAttribute('role', 'option');
                li.dataset.index = String(i);
                li.textContent = opt.textContent;
                if (opt.disabled) {
                    li.setAttribute('aria-disabled', 'true');
                }
                list.appendChild(li);
                return li;
            });
            syncValue();
        }

        function syncValue() {
            var opt = select.options[select.selectedIndex];
            valueEl.textContent = opt ? opt.textContent : '';
            options.forEach(function (li, i) {
                var isSel = i === select.selectedIndex;
                li.setAttribute('aria-selected', isSel ? 'true' : 'false');
                li.classList.toggle('is-selected', isSel);
            });
        }

        function setActive(li) {
            if (activeLi) {
                activeLi.classList.remove('is-active');
            }
            activeLi = li;
            if (li) {
                li.classList.add('is-active');
                trigger.setAttribute('aria-activedescendant', li.id);
                li.scrollIntoView({ block: 'nearest' });
            }
        }

        function position() {
            var r = trigger.getBoundingClientRect();
            // La lista crece al contenido, con al menos el ancho del trigger.
            list.style.minWidth = r.width + 'px';
            var listW = list.offsetWidth;
            var left = Math.min(r.left, window.innerWidth - listW - 8);
            list.style.left = Math.max(8, left) + 'px';

            var below = window.innerHeight - r.bottom;
            var listH = Math.min(list.scrollHeight, 264);
            if (below < listH + 12 && r.top > below) {
                list.style.top = (r.top - listH - 6) + 'px';
            } else {
                list.style.top = (r.bottom + 6) + 'px';
            }
        }

        function onScroll() {
            if (open) {
                position();
            }
        }

        function openList() {
            if (select.disabled || open) {
                return;
            }
            registry.forEach(function (other) {
                if (other !== instance) {
                    other.close();
                }
            });
            open = true;
            if (list.parentNode !== document.body) {
                document.body.appendChild(list);
            }
            list.hidden = false;
            position();
            wrapper.classList.add('is-open');
            list.classList.add('is-open');
            trigger.setAttribute('aria-expanded', 'true');
            setActive(list.querySelector('.is-selected') || options[0]);
            window.addEventListener('scroll', onScroll, true);
            window.addEventListener('resize', onScroll);
        }

        function closeList() {
            if (!open) {
                return;
            }
            open = false;
            list.hidden = true;
            list.classList.remove('is-open');
            wrapper.classList.remove('is-open');
            trigger.setAttribute('aria-expanded', 'false');
            trigger.removeAttribute('aria-activedescendant');
            window.removeEventListener('scroll', onScroll, true);
            window.removeEventListener('resize', onScroll);
        }

        function choose(i) {
            if (!select.options[i] || select.options[i].disabled) {
                return;
            }
            if (select.selectedIndex !== i) {
                select.selectedIndex = i;
                select.dispatchEvent(new Event('change', { bubbles: true }));
            }
            syncValue();
            closeList();
            trigger.focus();
        }

        function moveActive(dir) {
            var start = activeLi ? parseInt(activeLi.dataset.index, 10) : select.selectedIndex;
            var i = start;
            for (var c = 0; c < options.length; c++) {
                i = (i + dir + options.length) % options.length;
                if (!select.options[i].disabled) {
                    setActive(options[i]);
                    break;
                }
            }
        }

        trigger.addEventListener('click', function () {
            open ? closeList() : openList();
        });

        trigger.addEventListener('keydown', function (event) {
            if (['ArrowDown', 'ArrowUp', 'Enter', ' '].indexOf(event.key) !== -1) {
                event.preventDefault();
                if (!open) {
                    openList();
                } else if (event.key === 'ArrowDown') {
                    moveActive(1);
                } else if (event.key === 'ArrowUp') {
                    moveActive(-1);
                } else if (activeLi) {
                    choose(parseInt(activeLi.dataset.index, 10));
                }
            } else if (event.key === 'Escape' && open) {
                event.preventDefault();
                closeList();
            } else if ((event.key === 'Home' || event.key === 'End') && open) {
                // Primera y última opción, como en un <select> nativo.
                event.preventDefault();
                if (event.key === 'Home') {
                    setActive(options[0] || null);
                    if (options[0] && select.options[0].disabled) {
                        moveActive(1);
                    }
                } else {
                    setActive(options[options.length - 1] || null);
                    if (options.length && select.options[options.length - 1].disabled) {
                        moveActive(-1);
                    }
                }
            } else if (event.key === 'Tab' && open) {
                // El foco se va: la lista no puede quedarse flotando sobre la
                // página sin dueño. No se previene el Tab, sigue su camino.
                closeList();
            }
        });

        list.addEventListener('click', function (event) {
            var li = event.target.closest('.admin-select__option');
            if (li && li.getAttribute('aria-disabled') !== 'true') {
                choose(parseInt(li.dataset.index, 10));
            }
        });

        list.addEventListener('mousemove', function (event) {
            var li = event.target.closest('.admin-select__option');
            if (li) {
                setActive(li);
            }
        });

        document.addEventListener('click', function (event) {
            if (open && !wrapper.contains(event.target) && !list.contains(event.target)) {
                closeList();
            }
        });

        // Sincroniza si el valor cambia por código (u otro listener).
        select.addEventListener('change', syncValue);

        var instance = { close: closeList };
        registry.push(instance);
        instancias.push({ select: select, rebuild: build });

        build();
    }

    function initCustomSelects(root) {
        (root || document).querySelectorAll('select:not([data-native])').forEach(enhance);
    }

    /**
     * Repinta las opciones de un select ya realzado.
     *
     * El listener de 'change' solo sincroniza el valor mostrado; cuando el
     * consumidor reescribe los <option> (el POS refresca la lista de meseros en
     * cada sondeo) hay que regenerar los <li> del portal.
     */
    function refreshCustomSelect(select) {
        for (var i = 0; i < instancias.length; i++) {
            if (instancias[i].select === select) {
                instancias[i].rebuild();
                return true;
            }
        }
        return false;
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function () { initCustomSelects(document); });
    } else {
        initCustomSelects(document);
    }

    window.AdminSelect = { init: initCustomSelects, refresh: refreshCustomSelect };
})();
